503	 * Security invariants (audited): the GRANT is pinned to the exact db via
504	 * escapeGrantDbName (no wildcard bleed into a peer's db), it is NEVER `*.*`,
505	 * and `ALL PRIVILEGES` at database scope confers no global FILE/SUPER (those
506	 * are server-level and cannot be granted by a db-scoped GRANT). Returns plain
507	 * SQL with real backticks; the caller shell-escapes for `mysql -e`.
508	 */
509	export function buildScopedGrantSql(dbName: string, dbUser: string, dbPass: string): string {
510	  const grantName = escapeGrantDbName(dbName);
511	  return (
512	    `CREATE DATABASE IF NOT EXISTS \`${dbName}\`; ` +
513	    `CREATE USER IF NOT EXISTS '${dbUser}'@'localhost' IDENTIFIED BY '${dbPass}'; ` +
514	    `GRANT ALL PRIVILEGES ON \`${grantName}\`.* TO '${dbUser}'@'localhost'; ` +
515	    `FLUSH PRIVILEGES;`
516	  );
517	}
