561	    `CREATE USER IF NOT EXISTS '${mgrUser}'@'localhost' IDENTIFIED BY '${mgrPass}'; ` +
562	    `ALTER USER '${mgrUser}'@'localhost' IDENTIFIED BY '${mgrPass}'; ` +
563	    `GRANT ALL PRIVILEGES ON \`${scope}\`.* TO '${mgrUser}'@'localhost'; ` +
564	    `FLUSH PRIVILEGES;`
565	  );
566	}
