144	 * can't 301-loop a visitor into an untrusted-cert dead end). Shared IP; routed
145	 * purely by server_name; PHP proxied to THIS account's socket only, root jailed to
146	 * its webroot. Pure string — no interpolation reaches a shell here.
147	 */
148	function renderHostingVhost(
149	  username: string,
150	  domain: string,
151	  webroot: string,
152	  sock: string,
153	  ssl: { certDir: string; real: boolean },
154	  // Extra server_name ALIASES kept alongside the primary domain (each also gets a
155	  // `www.` variant). Used by taskSetPrimaryDomain to KEEP the old primary address
156	  // serving after a domain is promoted. Defaults to none → server_name is exactly
157	  // `${domain} www.${domain}` as before (back-compat).
158	  aliases: string[] = [],
159	): string {
160	  // `${domain} www.${domain}` plus, for each alias, `${alias} www.${alias}`. Every
161	  // name has already cleared isValidHostingDomain before reaching here.
162	  const serverName = [domain, ...aliases]
163	    .filter((d) => typeof d === "string" && d.length > 0)
164	    .flatMap((d) => [d, `www.${d}`])
165	    .join(" ");
166	  const phpLoc = [
167	    `    location ~ \\.php$ {`,
168	    `        include fastcgi_params;`,
169	    `        fastcgi_pass unix:${sock};`,
170	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
171	    `    }`,
172	  ].join("\n");
173	  const body = [
174	    `    root ${webroot};`,
175	    // Refuse to follow a symlink whose target isn't owned by the same user as the
176	    // link — blocks a tenant symlinking to a victim's wp-config.php that nginx
177	    // (www-data) would otherwise happily serve (cross-tenant read, audit CRITICAL-1).
178	    `    disable_symlinks if_not_owner;`,
179	    `    index index.php index.html;`,
180	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
181	    phpLoc,
182	    `    location ~ /\\. { deny all; }`,
183	  ].join("\n");
184	  const http = [
185	    `server {`,
186	    `    listen 80;`,
187	    `    listen [::]:80;`,
188	    `    server_name ${serverName};`,
189	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
190	    // Redirect to HTTPS only with a REAL cert; a self-signed site serves over 80 too.
191	    ssl.real ? `    location / { return 301 https://$host$request_uri; }` : body,
192	    `}`,
193	  ].join("\n");
194	  const https = [
195	    `server {`,
196	    `    listen 443 ssl;`,
197	    `    listen [::]:443 ssl;`,
198	    `    server_name ${serverName};`,
199	    `    ssl_certificate ${ssl.certDir}/fullchain.pem;`,
200	    `    ssl_certificate_key ${ssl.certDir}/privkey.pem;`,
201	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
202	    body,
203	    `}`,
204	  ].join("\n");
205	  return `${http}\n${https}\n`;
206	}
