286	/**
287	 * The isolation shell for one account (HTTP-only vhost; SSL added later by the
288	 * sweep once DNS points at us). Every interpolated value has already cleared a
289	 * validator, so nothing here can be a shell metacharacter.
290	 */
291	async function applyIsolation(
292	  conn: Client,
293	  a: { username: string; primaryDomain: string; diskQuotaMB: number; sftpPassword: string },
294	  php: string,
295	): Promise<void> {
296	  const u = a.username;
297	  const d = a.primaryDomain;
298	  if (!isValidUnixUsername(u)) throw new Error(`refusing unsafe username ${u}`);
299	  if (!isValidHostingDomain(d)) throw new Error(`refusing unsafe domain ${d}`);
300	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
301	  const { home, webroot } = accountPaths(u);
302	  const quotaGB = Math.max(1, Math.round(a.diskQuotaMB / 1024));
303	  const hardBlocks = diskQuotaBlocks(quotaGB);
304	  const softBlocks = Math.floor(hardBlocks * 0.95);
305	  const inodes = diskQuotaInodes(quotaGB);
306	  const sock = `/run/php/${u}.sock`;
307	
308	  // 1. Jailed user. Home is ROOT-owned (a chroot requirement); the user owns only
309	  //    public_html + tmp under it. nologin shell — SFTP-only via the chroot below.
310	  //
311	  // Perms come from the tested accountFsPlan(): home 711 (chroot-safe + nginx can
312	  // TRAVERSE to the webroot but a peer tenant can't LIST the home), webroot
313	  // 2750 <user>:www-data (nginx reads via the www-data GROUP, never world — the
314	  // old world-readable 755 let any tenant read a neighbour's wp-config.php if
315	  // open_basedir was escaped; the setgid bit keeps tenant-created files in the
316	  // www-data group so nginx keeps serving them), tmp 700 (private PHP scratch).
317	  const fs = accountFsPlan(u);
318	  await run(conn, "create user", `id -u ${u} >/dev/null 2>&1 || useradd -m -d ${home} -s /usr/sbin/nologin ${u}`);
319	  await run(
320	    conn,
321	    "chroot-safe home",
322	    `mkdir -p ${webroot} ${home}/tmp && ` +
323	      `chown ${fs.home.owner} ${home} && chmod ${fs.home.mode} ${home} && ` +
324	      `chown ${fs.webroot.owner} ${webroot} && chmod ${fs.webroot.mode} ${webroot} && ` +
325	      `chown ${fs.tmp.owner} ${home}/tmp && chmod ${fs.tmp.mode} ${home}/tmp`,
326	  );
327	  await run(conn, "sftp password", `printf '%s:%s' ${u} '${a.sftpPassword}' | chpasswd`);
328	
329	  // 2. Disk quota (fs must have usrquota — node onboarding enables it). The last
330	  //    two fields are the INODE soft/hard limits: `0 0` = unlimited inodes, which
331	  //    let a tenant exhaust the shared filesystem's inode table with millions of
332	  //    tiny files (a DoS the block quota can't stop), so we pass real caps (HIGH-2).
333	  await run(conn, "disk quota", `command -v setquota >/dev/null 2>&1 && setquota -u ${u} ${softBlocks} ${hardBlocks} ${inodes.soft} ${inodes.hard} /home || echo 'quota tool absent — skipped'`);
334	
335	  // 3. Per-user PHP-FPM pool — THE PHP isolation boundary.
336	  await writeFpmPool(conn, u, home, webroot, php);
337	
338	  // 4. Self-signed FALLBACK cert, so nginx can listen on 443 from the very first
339	  //    second the account exists. Without this the account served HTTP-only until
340	  //    the SSL sweep ran, and any visitor hitting https:// got ERR_CONNECTION_REFUSED
341	  //    while the panel already said "active" (the kaymo failure). Idempotent: only
342	  //    generated if absent. Key is 600 root; the whole dir is root-owned + off the
343	  //    tenant tree, so a tenant can never read or swap its own TLS key.
344	  const ssCertDir = selfSignedCertDir(u);
345	  await run(
346	    conn,
347	    "self-signed fallback cert",
348	    `mkdir -p ${ssCertDir} && chmod 700 ${ssCertDir} && ` +
349	      `if [ ! -s ${ssCertDir}/fullchain.pem ] || [ ! -s ${ssCertDir}/privkey.pem ]; then ` +
350	      `openssl req -x509 -newkey rsa:2048 -nodes -keyout ${ssCertDir}/privkey.pem -out ${ssCertDir}/fullchain.pem ` +
351	      `-days 3650 -subj "/CN=${d}" -addext "subjectAltName=DNS:${d},DNS:www.${d}"; fi && ` +
352	      `chown -R root:root ${ssCertDir} && chmod 600 ${ssCertDir}/privkey.pem && chmod 644 ${ssCertDir}/fullchain.pem`,
353	  );
354	
355	  // 5. Name-based vhost — ALWAYS listens on 443. Default: the self-signed fallback
356	  //    until the SSL sweep swaps in a real cert. But a FREE SUBDOMAIN covered by the
357	  //    node's wildcard cert (`*.<base>`) gets the REAL wildcard immediately — instant
358	  //    trusted HTTPS, no per-subdomain LE issuance — WHEN the wildcard is enabled AND
359	  //    the cert is actually present on the node (guarded so nginx -t can never fail on
360	  //    a missing ssl_certificate). Flag off ⇒ this branch is skipped ⇒ exactly the
361	  //    prior self-signed behaviour.
362	  let vhostSsl: { certDir: string; real: boolean } = { certDir: ssCertDir, real: false };
363	  if (hostingWildcardEnabled() && wildcardCoversHost(d)) {
364	    const wild = wildcardCertLiveDir();
365	    if (await fileExistsOnNode(conn, `${wild}/fullchain.pem`)) vhostSsl = { certDir: wild, real: true };
366	  }
367	  await installVhost(conn, u, renderHostingVhost(u, d, webroot, sock, vhostSsl));
368	
369	  // 5b. Branded placeholder so the account serves a real "site is ready" page from the
370	  //     first second (not a bare 403) until files are uploaded or an app is installed.
371	  await seedParkingPage(conn, fs.webroot.owner, webroot, d);
372	
373	  // 6. Chrooted SFTP — sshd -t GUARDED so a bad config can never lock out the box.
374	  const sftpConf = [
375	    `Match User ${u}`,
376	    `    ChrootDirectory ${home}`,
377	    `    ForceCommand internal-sftp`,
378	    `    AllowTcpForwarding no`,
379	    `    X11Forwarding no`,
380	  ].join("\n");
381	  const sshdFile = `/etc/ssh/sshd_config.d/nxeon-${u}.conf`;
382	  await run(
383	    conn,
384	    "sftp chroot (guarded)",
385	    // Write to a temp include, validate the WHOLE sshd config, and only then move
386	    // it into place + reload. If sshd -t fails, discard — never reload a broken config.
387	    `mkdir -p /etc/ssh/sshd_config.d && cat > ${sshdFile}.new <<'SSHD'\n${sftpConf}\nSSHD\n` +
388	      `cp -f ${sshdFile}.new ${sshdFile} && if sshd -t 2>/dev/null; then systemctl reload ssh 2>/dev/null || systemctl reload sshd; else rm -f ${sshdFile}; echo 'sshd -t rejected the chroot block — SFTP not enabled, box untouched'; fi; rm -f ${sshdFile}.new`,
389	  );
390	}
