1596	  if (!addon) throw new Error("addon domain not found");
1597	  if (addon.status !== "ACTIVE") throw new Error("the domain is still being set up");
1598	  const u = a.username;
1599	  const newDomain = addon.domain;
1600	  const oldDomain = a.primaryDomain;
1601	  if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
1602	  if (!isValidHostingDomain(newDomain)) throw new Error("unsafe new primary domain");
1603	  if (!isValidHostingDomain(oldDomain)) throw new Error("unsafe old primary domain");
