1631	  // ADDON → PRIMARY); the old domain keeps its existing claim as the served alias.
1632	  await db.hostingAccount.update({
1633	    where: { id: a.id },
1634	    data: { primaryDomain: newDomain, sslActive: haveReal, recheckRequested: true },
1635	  });
