1648	  // Lifecycle tasks deliberately run on a NON-active account: the admin action
1649	  // flips status to SUSPENDED / DELETING *before* queuing, so gating them on ACTIVE
1650	  // (like the content tasks) would make suspend/terminate silent no-ops — the kill
1651	  // switch must still fire. Content tasks (PHP/WP/backup/restore) stay ACTIVE-only.
1652	  const isLifecycle = task.kind === "SUSPEND" || task.kind === "UNSUSPEND" || task.kind === "TERMINATE";
1653	  if (!isLifecycle && a.status !== "ACTIVE") { await failTask(task.id, "the account is not active"); return; }
1654	  try {
1655	    const conn = await connectNode(a.node);
1656	    try {
1657	      let result: string | null = null;
1658	      if (task.kind === "PHP_SWITCH") await taskPhpSwitch(conn, a, task.payload);
1659	      else if (task.kind === "WORDPRESS_INSTALL") result = await taskWordpressInstall(conn, a, task.payload);
1660	      else if (task.kind === "APP_INSTALL") result = await taskAppInstall(conn, a, task.payload);
1661	      else if (task.kind === "BACKUP") await taskBackup(conn, a, task.id);
1662	      else if (task.kind === "RESTORE") await taskRestore(conn, a, task.payload);
1663	      else if (task.kind === "SUSPEND") await taskSuspend(conn, a);
1664	      else if (task.kind === "UNSUSPEND") await taskUnsuspend(conn, a);
1665	      else if (task.kind === "TERMINATE") await taskTerminate(conn, a);
1666	      else if (task.kind === "CREATE_SUBDOMAIN") await taskCreateSubdomain(conn, a, task.payload);
1667	      else if (task.kind === "DELETE_SUBDOMAIN") await taskDeleteSubdomain(conn, a, task.payload);
1668	      else if (task.kind === "CREATE_ADDON_DOMAIN") await taskCreateAddonDomain(conn, a, task.payload);
1669	      else if (task.kind === "DELETE_ADDON_DOMAIN") await taskDeleteAddonDomain(conn, a, task.payload);
1670	      else if (task.kind === "CREATE_CRON") await taskCreateCron(conn, a, task.payload);
1671	      else if (task.kind === "DELETE_CRON") await taskDeleteCron(conn, a, task.payload);
1672	      else if (task.kind === "INSTALL_DBTOOL") result = await taskInstallDbTool(conn, a, task.payload);
1673	      else if (task.kind === "ENSURE_DBMGR") await taskEnsureDbMgr(conn, a);
1674	      else if (task.kind === "APPLY_PLAN_LIMITS") await taskApplyPlanLimits(conn, a);
