1676	      // value until it is regenerated at deploy (same as HostingAccount.termMonths).
1677	      else if ((task.kind as string) === "RESET_DB_PASSWORD") await taskResetDbPassword(conn, a, task.payload);
1678	      else if ((task.kind as string) === "SET_PRIMARY_DOMAIN") result = await taskSetPrimaryDomain(conn, a, task.payload);
1679	      await db.hostingTask.update({ where: { id: task.id }, data: { status: "DONE", result, error: null } });
1680	      // FINALIZE a termination. taskTerminate deprovisions the node (vhost, FPM, DBs,
1681	      // jailed user, hostname claims) but the account row itself lived on in DELETING
1682	      // forever — nothing removed it — so the admin list showed accounts stuck
1683	      // "deleting" indefinitely. Now that the node is clean, delete the row; every
1684	      // child (tasks incl. this one, databases, subdomains, addons, crons, backups)
1685	      // is onDelete:Cascade, so the account and its history drop in one statement and
1686	      // it disappears from the panel. Financial history rides the user/wallet, not the
1687	      // account, so nothing billable is lost.
1688	      if (task.kind === "TERMINATE") {
