1690	          // Extremely unlikely (all FKs cascade); if it ever fails, at least don't
1691	          // leave it wedged in DELETING — surface it as FAILED so an operator sees it.
1692	          await db.hostingAccount.update({ where: { id: a.id }, data: { status: "FAILED" } }).catch(() => {});
1693	        });
1694	      }
1695	    } finally { try { conn.end(); } catch { /* */ } }
