1553	export async function createSubdomain(accountId: string, label: string): Promise<HostingResult> {
1554	  const ctx = await ownedSiteAccount(accountId);
1555	  if ("error" in ctx) return { error: ctx.error };
1556	  const { a } = ctx;
1557	  const clean = String(label ?? "").trim().toLowerCase();
1558	  if (!isValidSubdomainLabel(clean)) return { error: "Enter a valid subdomain label — letters, digits and hyphens only." };
1559	  const fqdn = `${clean}.${a.primaryDomain}`;
1560	  if (!isValidHostingDomain(fqdn)) return { error: "That subdomain isn’t a valid hostname." };
1561	  // Reject if another tenant already claimed this exact hostname as an addon domain
1562	  // (or primary). fqdn @unique blocks subdomain↔subdomain; this closes the addon
1563	  // path (audit HIGH-1, reverse direction).
1564	  if (await isHostnameClaimed(fqdn)) {
1565	    return { error: "That hostname is already in use on Nxeon." };
1566	  }
1567	  const { docroot } = subdomainPaths(a.username, clean);
1568	  try {
1569	    await db.$transaction(async (tx) => {
1570	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
1571	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
1572	      if (subs + addons >= a.maxSites) throw new Error("CAP");
1573	      const sub = await tx.hostingSubdomain.create({ data: { accountId: a.id, label: clean, fqdn, docroot, status: "PENDING" } });
1574	      // Atomic cross-tenant claim in the SAME tx: the UNIQUE(hostname) — not the
1575	      // advisory isHostnameClaimed read above — is what actually stops a co-tenant
1576	      // from committing this same server_name as their primary/subdomain/addon.
1577	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(fqdn), accountId: a.id, kind: "SUBDOMAIN" } });
1578	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_SUBDOMAIN", payload: JSON.stringify({ subdomainId: sub.id }) } });
1579	    }, { isolationLevel: "Serializable" });
1580	  } catch (e) {
1581	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
1582	    if (isUniqueViolation(e)) return { error: "That hostname is already in use on Nxeon." };
1583	    return { error: "That subdomain already exists, or the request raced — try again." };
1584	  }
1585	  revalidatePath(`/dashboard/hosting/${accountId}`);
1586	  return { ok: true };
1587	}
