1735	export async function listWebsites(accountId: string): Promise<HostingWebsiteView[]> {
1736	  const user = await requireUser();
1737	  const a = await db.hostingAccount.findUnique({
1738	    where: { id: accountId },
1739	    select: { id: true, userId: true, username: true, primaryDomain: true, status: true, sslActive: true, phpVersion: true },
1740	  });
1741	  if (!a) return [];
1742	  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
1743	
1744	  const [subs, addons, tasks, metas] = await Promise.all([
1745	    db.hostingSubdomain.findMany({ where: { accountId, status: { not: "DELETING" } }, orderBy: { createdAt: "asc" } }),
1746	    db.hostingAddonDomain.findMany({ where: { accountId, status: { not: "DELETING" } }, orderBy: { createdAt: "asc" } }),
1747	    db.hostingTask.findMany({
1748	      where: { accountId, status: "DONE", kind: { in: ["WORDPRESS_INSTALL", "APP_INSTALL"] } },
1749	      orderBy: { createdAt: "desc" },
1750	      select: { kind: true, payload: true, result: true },
1751	    }),
1752	    // Customer-uploaded website thumbnails, keyed by the website's stable key.
1753	    db.hostingWebsiteMeta.findMany({ where: { accountId, thumbName: { not: null } }, select: { siteRef: true, updatedAt: true } }),
