157	    if (dupe) {
158	      return {
159	        error:
160	          dupe.userId === user.id
161	            ? "You already have a hosting account for this domain."
162	            : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.",
163	      };
164	    }
165	    // Also reject if this hostname is already someone's subdomain or addon domain
166	    // (audit HIGH-2: the primary-order guard used to ignore those two tables).
167	    if (await isHostnameClaimed(name)) {
168	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
169	    }
170	  }
