175	  // Managed first-month-free. `promoCharge` is $0 (a single-month hosting term is
176	  // free); `fullCharge` is the plan price. The credit is granted ONLY if the atomic
177	  // claim inside the charge tx succeeds — otherwise (already redeemed by this
178	  // account/IP, or the promo is off) the account is created at FULL price. We
179	  // pre-check eligibility only to pick the balance gate: a first-time customer with
180	  // a $0 balance can still sign up free, a repeat one is gated against full price.
181	  // First-month-free is scoped to Shared Web Hosting (this flow) — the one
182	  // product the promo applies to. See firstMonthFreeAppliesTo.
183	  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
184	  const campaign = promoCampaignFromCookie(await cookies());
185	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
186	  // Billing term (Monthly / Annual). The annual rate is the admin setting, resolved
187	  // ONCE here, frozen onto the account, charged up front and read back at renewal —
188	  // so displayed === charged === renewed. A malformed term falls back to monthly.
189	  const term = normalizeProductTerm(termMonthsRaw);
190	  const annualPct = await annualDiscountPct();
191	  const limits = planLimits(plan);
192	  // Optional extra storage bought at deploy (on-step, in-range). Priced per-GB/month
193	  // at the SAME rate VPS extra disk uses and multiplied over the whole term. It is an
194	  // ADD-ON: never discounted by the term promo (the free month applies to the plan
