229	      }
230	      name = freeSubdomainFor(label);
231	      if (!isValidHostingDomain(name)) return { error: "That subdomain isn’t a valid hostname — try a different one." };
232	      if (await isHostnameClaimed(name)) {
233	        return { error: `${name} is already taken — please choose another subdomain.` };
234	      }
235	    } else {
236	      name = tempSubdomainFor(username);
237	      if (!isValidHostingDomain(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
238	      if (await isHostnameClaimed(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
239	    }
240	  }
241	
242	  let accountId = "";
243	  try {
244	    await db.$transaction(async (tx) => {
245	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
246	      let debitCents = fullCharge;
247	      let promoClaimId: string | null = null;
248	      // MONEY BUG FIX (2026-08-12): gate the claim on `eligible`, NOT `promoEnabled`.
249	      // claimFirstMonthFree INSERTs a redemption row and catches the P2002 unique
250	      // violation ("already redeemed") to return {claimed:false}. But Postgres POISONS
251	      // the whole transaction the instant any statement fails — a caught error does
252	      // NOT un-abort it — so the very next statement (debitWallet's updateMany) then
253	      // dies with 25P02 ("current transaction is aborted"). Result: EVERY repeat
254	      // customer who already used the free month could no longer place a hosting order
255	      // (the order failed, wallet never charged). `eligible` is the same authoritative
256	      // per-user/per-IP precheck (firstMonthFreeEligible) resolved above, so an
257	      // ineligible/repeat customer now skips the doomed INSERT entirely and is charged
258	      // full price cleanly. The atomic anti-double-grant guarantee is preserved: two
259	      // concurrent ELIGIBLE orders still both run the claim, one wins, the loser's tx
260	      // poisons on P2002 and fails safe (no charge, no second free month) — retry pays
261	      // full. So exactly one free month is ever granted.
262	      if (eligible) {
263	        const claim = await claimFirstMonthFree(tx, {
264	          userId: user.id,
265	          ipHash,
266	          serviceType: "HOSTING",
267	          campaign,
268	          chargedCents: promoCharge,
269	        });
270	        if (claim.claimed) {
