272	          promoClaimId = claim.id;
273	        }
274	      }
275	      const note = (debitCents < fullCharge ? " — First month free" : "") + (extraGB > 0 ? ` + ${extraGB} GB storage` : "");
276	      // Term shown on the ledger line: an annual account reads "Annual ($X.XX/mo)"
