689	export async function revealHostingSftpPassword(accountId: string): Promise<{ password?: string; error?: string }> {
690	  const user = await requireUser();
691	  // An impersonating admin must not exfiltrate a customer's live SFTP credential
692	  // (matches orderHostingAccount/createHostingDatabase — audit LOW-1).
693	  await assertNotImpersonating();
694	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true, sftpPasswordEnc: true } });
695	  if (!a) return { error: "Not found." };
696	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
697	  const pw = a.sftpPasswordEnc ? decryptSecret(a.sftpPasswordEnc) : null;
698	  if (!pw) return { error: "No password on record yet — the account is still being set up." };
699	  return { password: pw };
700	}
