test("GRANT db-name escaping pins a grant to exactly one database", () => {
  // _ and % are LIKE-wildcards in GRANT — must be backslash-escaped.
  assert.equal(escapeGrantDbName("nxalice_wp"), "nxalice\\_wp");
  assert.equal(escapeGrantDbName("a%b"), "a\\%b");
  assert.equal(escapeGrantDbName("a\\b"), "a\\\\b");
