/**
 * The ordered, de-duplicated nginx `server_name` tokens for a primary domain plus
 * any attached ALIAS domains — each name paired with its `www.` variant. Pure so the
 * multi-tenant vhost routing (the security-critical bit) is unit-tested independently
 * of the node.
 *
 * Every name is re-validated (isValidHostingDomain) and dropped if malformed — a
 * blank/garbage alias can never reach the server_name — and duplicates collapse (an
 * alias equal to the primary, or two aliases that share a `www.` form, appear once).
 * The primary always leads. This is exactly what renderHostingVhost interpolates, and
 * what the attach/make-primary flows rely on to fold an added domain into the existing
 * website's vhost instead of minting a new docroot.
 */
export function hostingServerNames(primary: string, aliases: string[] = []): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const d of [primary, ...aliases]) {
    const h = String(d ?? "").trim().toLowerCase().replace(/\.$/, "");
    if (!isValidHostingDomain(h)) continue;
    for (const name of [h, `www.${h}`]) {
      if (!seen.has(name)) { seen.add(name); out.push(name); }
    }
  }
  return out;
}

