/**
 * The SSL cert dir the account's PRIMARY vhost should point at RIGHT NOW, chosen so
 * a reinstall never downgrades a live cert and `nginx -t` can never fail on a missing
 * file. Preference: the real per-domain Let's Encrypt cert for `primary` if present;
 * else the `*.<base>` WILDCARD cert when it covers `primary` (a free subdomain) and is
 * minted; else the account's self-signed fallback (always present). Mirrors the
 * selection applyIsolation + the SSL sweep already make.
 */
async function primaryVhostSsl(conn: Client, username: string, primary: string): Promise<{ certDir: string; real: boolean }> {
  const realLive = `/etc/letsencrypt/live/${primary}`;
  if ((await exec(conn, `test -s ${realLive}/fullchain.pem && echo yes || echo no`)).out.trim() === "yes") {
    return { certDir: realLive, real: true };
  }
  if (hostingWildcardEnabled() && wildcardCoversHost(primary)) {
    const wild = wildcardCertLiveDir();
    if (await fileExistsOnNode(conn, `${wild}/fullchain.pem`)) return { certDir: wild, real: true };
  }
  return { certDir: selfSignedCertDir(username), real: false };
}

/**
 * ATTACH an already-claimed domain to the account's PRIMARY website — add it as an
 * additional `server_name` on the existing `hosting-<user>.conf` (SAME docroot, no new
 * empty site) so it starts serving the customer's existing files. The domain is already
 * a PRIMARY-kind hostname claim (created atomically by attachDomainToWebsite), so
 * primaryAliasesFor folds it into the server_name automatically.
 *
 * Worst-case safe: the vhost keeps pointing at whatever real cert the primary already
 * has (primaryVhostSsl never downgrades), and `nginx -t` guards the reload — if
 * anything fails the old vhost stays. When a real per-domain cert exists we ALSO try a
 * best-effort `certbot --expand` to cover the new name, but only if the customer has
 * pointed DNS at us yet; `--allow-subset-of-names` + `--keep-until-expiring` make that
 * a no-op (never an error) when it hasn't resolved — the site still serves over the
 * existing cert (name-mismatch warning on the new name only) until DNS is set and the
 * customer makes it primary or the SSL sweep expands the cert. Never flips primaryDomain.
 */
async function attachPrimaryAlias(conn: Client, a: { id: string; username: string; primaryDomain: string }, newDomain: string): Promise<string> {
  const u = a.username;
  const primary = a.primaryDomain;
  if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
  if (!isValidHostingDomain(primary)) throw new Error("unsafe primary domain");
  if (!isValidHostingDomain(newDomain)) throw new Error("unsafe domain");
  const { webroot } = accountPaths(u);
  const sock = `/run/php/${u}.sock`;
  const ssl = await primaryVhostSsl(conn, u, primary);
  // primaryAliasesFor already includes newDomain (its PRIMARY claim exists), plus any
  // previously-attached aliases + the account's own historical primaries.
  const aliases = await primaryAliasesFor(a.id, primary);
  await installVhost(conn, u, renderHostingVhost(u, primary, webroot, sock, ssl, aliases));
  if (ssl.real && ssl.certDir === `/etc/letsencrypt/live/${primary}`) {
    // Best-effort widen the primary's real cert to the attached name(s). Failure is
    // swallowed (DNS not pointed yet) — the alias still serves over the existing cert.
    const names = hostingServerNames(primary, aliases).map((n) => `-d ${n}`).join(" ");
    await exec(conn, `certbot certonly --webroot -w /var/www/html ${names} --cert-name ${primary} --expand --allow-subset-of-names --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000).catch(() => undefined);
  }
  await db.hostingAccount.update({ where: { id: a.id }, data: { recheckRequested: true } }).catch(() => undefined);
  return JSON.stringify({ note: `${newDomain} is attached to this website. Point its DNS (A record) at us, then Make primary when you’re ready. ${primary} keeps working.` });
}

/**
 * Promote `newDomain` to be the account's PRIMARY (serving) domain for its MAIN
 * website (`public_html`), keeping the OLD primary as an ALIAS server_name so its
 * address keeps working. Shared by BOTH the legacy addon-promote flow (`addon` set —
 * its own separate vhost is torn down + row deleted) and the attached-domain
 * make-primary flow (`addon` null — the domain is already an alias on the primary
 * vhost). Order is chosen so the old address NEVER stops serving:
 *   1. Regenerate `hosting-<user>.conf` with newDomain as server_name + every other
 *      claimed name (incl. the old primary) as aliases. Cert dir is one GUARANTEED to
 *      exist (real cert for newDomain if present, else self-signed) so `nginx -t`
 *      can't fail on a missing file and 443 keeps listening.
 *   2. (addon path only) remove the addon's own vhost — its server_name now belongs to
 *      the primary; its docroot files are LEFT on disk.
 *   3. If WordPress lives in the primary docroot, rewrite its stored URLs.
 * Only after every node step succeeds do we flip DB `primaryDomain`, re-key the claim
 * (newDomain → PRIMARY; old stays claimed as the alias) and delete the addon row (if
 * any). On any failure we throw BEFORE the DB flip, so the account keeps its old primary
 * and — because the vhost already carries the old name as an alias — the old address
 * keeps serving. `sslActive` is reset unless a real cert for newDomain is already live,
 * so the SSL sweep issues/verifies one (folding the old primary in as an alias cert).
 */
async function promotePrimaryDomain(
  conn: Client,
  a: { id: string; username: string; primaryDomain: string },
  newDomain: string,
  addon: { id: string } | null,
): Promise<string> {
  const u = a.username;
  const oldDomain = a.primaryDomain;
  if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
  if (!isValidHostingDomain(newDomain)) throw new Error("unsafe new primary domain");
  if (!isValidHostingDomain(oldDomain)) throw new Error("unsafe old primary domain");
  if (newDomain === oldDomain) {
    // Already the primary (defensive) — just clean up any addon bookkeeping.
    if (addon) await db.hostingAddonDomain.delete({ where: { id: addon.id } }).catch(() => undefined);
    return JSON.stringify({ note: `${newDomain} is already your primary domain.` });
  }
  const { webroot } = accountPaths(u);
  const sock = `/run/php/${u}.sock`;

  // Pick a cert dir that DEFINITELY exists so `nginx -t` can never fail on it.
  const realLive = `/etc/letsencrypt/live/${newDomain}`;
  const haveReal = (await exec(conn, `test -s ${realLive}/fullchain.pem && echo yes || echo no`)).out.trim() === "yes";
  const certDir = haveReal ? realLive : selfSignedCertDir(u);

  // 1. Repoint the primary vhost: new domain as server_name, every other claimed name
  //    (incl. the old primary) kept as an alias so nothing stops serving.
  const aliases = await primaryAliasesFor(a.id, newDomain);
  await installVhost(conn, u, renderHostingVhost(u, newDomain, webroot, sock, { certDir, real: haveReal }, aliases));
  // 2. (addon path) drop the addon's own vhost — its server_name now belongs to the
  //    primary. Keep its docroot files on disk.
  if (addon) await removeNamedVhost(conn, `${u}-${newDomain}`);
  // 3. WordPress URL rewrite, when the PRIMARY docroot actually runs WordPress.
  const isWp = (await exec(conn, `sudo -u ${u} -H wp --path=${webroot} core is-installed >/dev/null 2>&1 && echo yes || echo no`)).out.trim() === "yes";
  if (isWp) {
    const wp = `sudo -u ${u} -H wp --path=${webroot}`;
    await run(conn, "wp search-replace", `${wp} search-replace '${oldDomain}' '${newDomain}' --all-tables --skip-columns=guid`);
    await run(conn, "wp home/siteurl", `${wp} option update home 'https://${newDomain}' && ${wp} option update siteurl 'https://${newDomain}'`);
  }

  // Node is consistent — commit the DB flip. Re-key the hostname claim (newDomain →
  // PRIMARY); the old domain keeps its existing claim as the served alias.
  await db.hostingAccount.update({
    where: { id: a.id },
    data: { primaryDomain: newDomain, sslActive: haveReal, recheckRequested: true },
  });
  await db.hostingHostnameClaim
    .updateMany({ where: { hostname: normalizeClaimHostname(newDomain) }, data: { kind: "PRIMARY" } })
    .catch(() => undefined);
  if (addon) await db.hostingAddonDomain.delete({ where: { id: addon.id } }).catch(() => undefined);
  return JSON.stringify({ note: `Primary domain is now ${newDomain}. ${oldDomain} still works.`, url: `https://${newDomain}/` });
}

/**
 * SET_PRIMARY_DOMAIN dispatcher — three payload modes, all reusing the primary-vhost
 * alias machinery so an added domain folds onto the EXISTING website's docroot rather
 * than a new empty site:
 *   { attachDomain }      → attach a claimed domain as an alias on the primary vhost.
 *   { makePrimaryDomain } → promote an already-attached domain to the primary address.
 *   { addonId }           → legacy: promote an ACTIVE addon domain to the primary.
 */
async function taskSetPrimaryDomain(
  conn: Client,
  a: { id: string; username: string; primaryDomain: string },
  payload: string | null,
): Promise<string> {
  const p = (() => { try { return JSON.parse(payload || "{}"); } catch { return {}; } })() as {
    attachDomain?: string; makePrimaryDomain?: string; addonId?: string;
  };
  if (p.attachDomain) return attachPrimaryAlias(conn, a, String(p.attachDomain));
  if (p.makePrimaryDomain) return promotePrimaryDomain(conn, a, String(p.makePrimaryDomain), null);
  const addonId = String(p.addonId ?? "");
  const addon = await db.hostingAddonDomain.findFirst({ where: { id: addonId, accountId: a.id } });
  if (!addon) throw new Error("addon domain not found");
  if (addon.status !== "ACTIVE") throw new Error("the domain is still being set up");
  return promotePrimaryDomain(conn, a, addon.domain, { id: addon.id });

