// ---------- Attach a real domain to an EXISTING website (docroot-sharing) --------

export type AttachedDomainView = { hostname: string; isPrimary: boolean };

/**
 * Every real domain ATTACHED to the account's primary website — the current primary
 * plus any additional PRIMARY-kind hostname claims folded into its vhost as aliases.
 * Owner or admin. Drives the "Domains on this website" list on the Domain & SSL tab.
 * (Our free `*.<base>` subdomains are shown too — they attach exactly the same way.)
 */
export async function listAttachedDomains(accountId: string): Promise<AttachedDomainView[]> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true, primaryDomain: true } });
  if (!a) return [];
  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  const primary = normalizeClaimHostname(a.primaryDomain);
  const claims = await db.hostingHostnameClaim.findMany({
    where: { accountId, kind: "PRIMARY" },
    select: { hostname: true },
    orderBy: { createdAt: "asc" },
  });
  const seen = new Set<string>();
  const rows: AttachedDomainView[] = [];
  // The account's live primary always leads (it may not carry its own claim row on
  // legacy accounts, so surface it explicitly).
  rows.push({ hostname: a.primaryDomain, isPrimary: true });
  seen.add(primary);
  for (const c of claims) {
    if (seen.has(c.hostname)) continue;
    seen.add(c.hostname);
    rows.push({ hostname: c.hostname, isPrimary: false });
  }
  return rows;
}

/**
 * Attach a real domain the customer owns to an EXISTING website so it serves the SAME
 * docroot/files — the missing "point this domain at my existing site" that createAddonDomain
 * (a NEW empty docroot) never did. Supported for the account's PRIMARY website — the site a
 * customer who started on a free subdomain already has.
 *
 * The domain is registered as an additional PRIMARY-kind hostname claim (the same atomic
 * cross-tenant UNIQUE(hostname) guard every hostname gets) so primaryAliasesFor folds it
 * into the primary vhost's `server_name` — the domain starts serving the existing files,
 * no new site, no maxSites consumed. A SET_PRIMARY_DOMAIN task (attach mode) reinstalls the
 * vhost + best-effort expands SSL. Nothing is promoted until the customer clicks Make
 * primary; the current address keeps serving throughout (worst-case safe).
 */
export async function attachDomainToWebsite(accountId: string, siteRef: string, domain: string): Promise<HostingResult> {
  const ctx = await ownedSiteAccount(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const { user, a } = ctx;
  // Docroot-sharing attach targets the primary website (public_html) — the site whose
  // vhost carries alias server_names. For a subdomain/addon site, "Buy a domain" adds a
  // new independent site instead (createAddonDomain), which is the right primitive there.
  if (siteRef !== "primary") {
    return { error: "Connect a domain from the plan’s main website. To give this site its own domain, add it from “Websites → Add website”." };
  }
  const name = normalizeHostingDomain(domain);
  if (!name || !isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
  if (name === a.primaryDomain) return { error: "That’s already this website’s address." };
  // Cross-tenant uniqueness across ALL hostname tables — a shared vhost keys on
  // server_name, so an attached name must not shadow anyone's primary/subdomain/addon.
  if (await isHostnameClaimed(name)) {
    return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
  }
  try {
    await db.$transaction(async (tx) => {
      // Atomic cross-tenant claim (kind PRIMARY = an alias on the primary website). The
      // UNIQUE(hostname) — not the advisory read above — is the authoritative guard: a
      // co-tenant racing the same name fails here (P2002) and rolls the whole tx back.
      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: a.id, kind: "PRIMARY" } });
      await tx.hostingTask.create({
        data: { accountId: a.id, kind: "SET_PRIMARY_DOMAIN" as Prisma.HostingTaskUncheckedCreateInput["kind"], payload: JSON.stringify({ attachDomain: name }) },
      });
    }, { isolationLevel: "Serializable" });
  } catch (e) {
    if (isUniqueViolation(e)) return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
    return { error: "Couldn’t attach that domain, or the request raced — try again." };
  }
  await db.auditLog.create({ data: { userId: user.id, action: "hosting.attachdomain", detail: `${name} → ${a.primaryDomain}` } }).catch(() => {});
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

/**
 * Make an already-ATTACHED domain the primary (serving) address of the account's main
 * website — regenerate its vhost with the new domain leading, keep the old address as an
 * alias/redirect so nothing breaks, reissue/expand SSL, and (worker-side) run `wp
 * search-replace` + update home/siteurl when WordPress is detected in the docroot.
 *
 * The DB `primaryDomain` is NOT flipped here — the worker (promotePrimaryDomain, via the
 * SET_PRIMARY_DOMAIN task) flips it only after the node vhost + WP rewrite succeed,
 * keeping the old address serving in the meantime (worst-case safe). The domain must
 * already be attached to THIS account (a PRIMARY-kind claim). Idempotent against
 * double-click: refuses while a primary-domain change is already queued/running.
 */
export async function setWebsitePrimaryDomain(accountId: string, siteRef: string, domain: string): Promise<HostingResult> {
  const user = await requireUser();
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, primaryDomain: true } });
  if (!a) return { error: "Account not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
  if (siteRef !== "primary") return { error: "Make-primary applies to the plan’s main website." };
  const name = normalizeHostingDomain(domain);
  if (!name || !isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
  if (name === a.primaryDomain) return { error: "That’s already this website’s primary address." };
  // The domain must already be attached to THIS account (owned PRIMARY-kind claim).
  const claim = await db.hostingHostnameClaim.findUnique({ where: { hostname: normalizeClaimHostname(name) }, select: { accountId: true } });
  if (!claim || claim.accountId !== a.id) return { error: "Connect the domain to this website first, then make it primary." };
  const inFlight = await db.hostingTask.findFirst({
    where: { accountId, kind: "SET_PRIMARY_DOMAIN" as Prisma.HostingTaskUncheckedCreateInput["kind"], status: { in: ["PENDING", "RUNNING"] } },
  });
  if (inFlight) return { error: "A primary-domain change is already in progress." };
  await db.hostingTask.create({
    data: {
      accountId,
      kind: "SET_PRIMARY_DOMAIN" as Prisma.HostingTaskUncheckedCreateInput["kind"],
      payload: JSON.stringify({ makePrimaryDomain: name, oldDomain: a.primaryDomain }),
    },
  });
  await db.auditLog.create({ data: { userId: user.id, action: "hosting.setprimary", detail: `${a.primaryDomain} → ${name}` } }).catch(() => {});
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

