/**
 * A quota fill bar that animates 0 → its value on mount (violet→cyan, ~750ms ease).
 * Respects prefers-reduced-motion: reduced-motion users get the final state with no
 * transition. A tiny floor keeps a non-zero value visible even near 0%.
 */
function UsageBar({ pct }: { pct: number }) {
  const target = pct <= 0 ? 0 : Math.max(4, Math.min(100, pct));
  const [w, setW] = useState(0);
  useEffect(() => {
    const reduce = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (reduce) { setW(target); return; }
    const r = requestAnimationFrame(() => setW(target));
    return () => cancelAnimationFrame(r);
  }, [target]);
  const full = pct >= 100;
  return (
    <div className="mt-3 h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]" role="progressbar" aria-valuenow={Math.round(pct)} aria-valuemin={0} aria-valuemax={100}>
      <div
        className={`h-full rounded-full bg-gradient-to-r transition-[width] duration-700 ease-out motion-reduce:transition-none ${full ? "from-amber-400 to-amber-300" : "from-brand-400 to-accent-cyan"}`}
        style={{ width: `${w}%` }}
      />
    </div>
  );
}

/**
 * A resource stat-card that mirrors the shared StatCard styling but adds an animated
 * quota bar (when a quota is known) + an optional sub-line (e.g. the folded-in Inodes
 * count on Storage). Renders as a button when `onClick` is given so the whole card
 * stays a section-nav target, exactly like the plain StatCards around it.
 */
function QuotaStatCard({
  label, value, icon, used, total, sub, onClick,
}: {
  label: string; value: string; icon: ReactNode;
  used?: number | null; total?: number | null; sub?: string; onClick?: () => void;
}) {
  const pct = used != null && total != null && total > 0 ? Math.min(100, Math.round((used / total) * 100)) : null;
  const inner = (
    <div className="card card-hover flex h-full flex-col justify-between p-5 text-left">
      <div className="flex items-start justify-between">
        <div className="min-w-0">
          <p className="text-[13px] text-slate-400">{label}</p>
          <p className="mt-1.5 text-2xl font-bold tracking-tight">{value}</p>
        </div>
        <div className="rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 p-2.5 text-brand-300">
          {icon}
        </div>
      </div>
      {pct !== null ? <UsageBar pct={pct} /> : sub ? <div className="mt-3 h-1.5" /> : null}
      {sub && <p className="mt-1.5 text-[11px] text-slate-500">{sub}</p>}
    </div>
  );
  return onClick ? (
    <button type="button" onClick={onClick} className="block h-full w-full">{inner}</button>
  ) : inner;
}

