          {site.kind !== "primary" && <button className="btn-secondary text-sm" onClick={() => onSection("domains")}>Connect / buy a domain</button>}
        </div>
      </div>

      {/* The keystone: attach a real domain to THIS existing website (same files) and
          make it primary — only for the plan's main website (public_html). */}
      {site.kind === "primary" && <ConnectDomainCard account={account} site={site} onSitesChanged={onSitesChanged} />}

      {(site.kind === "subdomain" || site.kind === "addon") && (
