}

/**
 * Connect a real domain to the EXISTING main website (same docroot/files) and promote
 * it to the primary address — the "point this domain at my existing site" flow. Attach
 * adds the domain as an alias on the current vhost (no new empty site); Make primary
 * repoints the site onto it, keeping the old address as an alias so nothing breaks.
 */
function ConnectDomainCard({
  account, site, onSitesChanged,
}: {
  account: HostingAccountView; site: HostingWebsiteView; onSitesChanged: () => void;
}) {
  const [domains, setDomains] = useState<AttachedDomainView[] | null>(null);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const load = useCallback(() => {
    listAttachedDomains(account.id).then(setDomains).catch(() => setDomains([]));
  }, [account.id]);
  useEffect(() => { load(); }, [load]);

  async function attach() {
    const d = input.trim().toLowerCase();
    if (!d) return;
    setBusy(true); setErr("");
    const r = await attachDomainToWebsite(account.id, "primary", d);
    setBusy(false);
    if (r.error) { setErr(r.error); return; }
    setInput("");
    load();
    onSitesChanged();
  }
  async function makePrimary(hostname: string) {
    if (!confirm(`Make ${hostname} the primary address for this website? ${site.hostname} keeps working as an alias, and WordPress URLs are updated automatically.`)) return;
    setBusy(true); setErr("");
    const r = await setWebsitePrimaryDomain(account.id, "primary", hostname);
    setBusy(false);
    if (r.error) { setErr(r.error); return; }
    load();
    onSitesChanged();
  }

  const extras = (domains ?? []).filter((d) => !d.isPrimary);

  return (
    <div className="card max-w-2xl">
      <h3 className="mb-1 flex items-center gap-2 font-semibold"><Icon name="globe" size={16} className="text-brand-300" /> Connect a domain</h3>
      <p className="mb-4 text-sm text-slate-400">
        Point a domain you own at <span className="font-mono text-xs text-slate-300">{site.hostname}</span> — it serves the
        same files, no new empty site. Then make it your primary address whenever you&apos;re ready; your current address keeps working.
      </p>

      <div className="flex flex-wrap items-end gap-2">
        <div className="min-w-0 flex-1">
          <label className="label" htmlFor="attach-domain">Domain you own</label>
          <input
            id="attach-domain"
            className="input font-mono text-sm"
            placeholder="example.com"
            value={input}
            disabled={busy}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") attach(); }}
          />
        </div>
        <button className="btn-primary inline-flex items-center gap-1.5 text-sm" disabled={busy || !input.trim()} onClick={attach}>
          <Icon name="link" size={15} /> {busy ? "Working…" : "Connect"}
        </button>
        <a href="/dashboard/domains/register" className="btn-secondary inline-flex items-center gap-1.5 text-sm">
          <Icon name="search" size={15} /> Buy a domain
        </a>
      </div>
      {err && <p className="mt-2 text-sm text-red-400">{err}</p>}

      <div className="mt-5 border-t border-white/[0.06] pt-4">
        <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500">Domains on this website</p>
        {domains === null ? (
          <p className="text-sm text-slate-500">Loading…</p>
        ) : (
          <ul className="space-y-2">
            {(domains ?? []).map((d) => (
              <li key={d.hostname} className="flex flex-wrap items-center gap-x-3 gap-y-1 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
                <span className="min-w-0 flex-1 truncate font-mono text-xs text-slate-200">{d.hostname}</span>
                {d.isPrimary ? (
                  <Badge tone="brand">Primary</Badge>
                ) : (
                  <>
                    {!isFreeNxeonHost(d.hostname, account.subdomainBase) && (
                      <span className="text-[11px] text-slate-500">
                        A record → <span className="font-mono text-brand-200">{account.pointToA}</span>
                      </span>
                    )}
                    <button className="btn-secondary inline-flex items-center gap-1 px-2.5 py-1 text-xs" disabled={busy} onClick={() => makePrimary(d.hostname)}>
                      <Icon name="star" size={13} /> Make primary
                    </button>
                  </>
                )}
              </li>
            ))}
          </ul>
        )}
        {extras.length > 0 && (
          <p className="mt-3 text-[11px] text-slate-500">
            Newly connected domains serve your site right away over HTTP. Point their <span className="font-mono text-slate-300">A</span> record at
            us and HTTPS is issued automatically; once resolving, click <span className="text-slate-300">Make primary</span> to switch your main address over.
          </p>
        )}
      </div>
    </div>
  );
}

/** True for one of our free `*.<base>` wildcard subdomains (resolves + gets HTTPS
 *  automatically — no A record for the customer to set). */
function isFreeNxeonHost(host: string, base: string): boolean {
  const h = host.trim().toLowerCase().replace(/\.$/, "");
  return h === base || h.endsWith(`.${base}`);
}

