test("hostingServerNames pairs each name with www, de-dupes, drops junk, primary leads", () => {
  // Primary + one alias → both with their www. variants, primary first.
  assert.deepEqual(
    hostingServerNames("example.com", ["shop.example.com"]),
    ["example.com", "www.example.com", "shop.example.com", "www.shop.example.com"],
  );
  // No aliases → just the primary pair (back-compat with the old inline builder).
  assert.deepEqual(hostingServerNames("example.com"), ["example.com", "www.example.com"]);
  // An alias equal to the primary collapses (no duplicate server_name for nginx).
  assert.deepEqual(hostingServerNames("example.com", ["example.com"]), ["example.com", "www.example.com"]);
  // Malformed/blank aliases are dropped — a garbage name can never reach server_name.
  assert.deepEqual(
    hostingServerNames("example.com", ["", "no-tld", "a b.com", "ok.io"]),
    ["example.com", "www.example.com", "ok.io", "www.ok.io"],
  );
});

